/*********************************************************************** 
 * 함수명    : fn_setItem()
 * 파라메터 : vIdx(순서), strNm(항목명), strCd(항목ID), dtsObj(데이터셋)
 * 설명       : 일반 데이터에 대해 Row 표시
 ***********************************************************************/
scwin.fn_setItem = function(vIdx, strNm, strCd, dtsObj) {
    dts_List.setCellData(vIdx, 'ITEM', strNm);
    dts_List.setCellData(vIdx, 'NEWLIST_REQ', dtsObj.getCellData(1, strCd));
    dts_List.setCellData(vIdx, 'EXEM_REQ', dtsObj.getCellData(2, strCd));
    dts_List.setCellData(vIdx, 'CORRYN', scwin.fn_sameYn(dtsObj.getCellData(1, strCd), dtsObj.getCellData(2, strCd)));
};


/*********************************************************************** 
 * 함수명    : fn_setItem_Date()
 * 파라메터 : vIdx(순서), strNm(항목명), strCd(항목ID), dtsObj(데이터셋)
 * 설명       : 날짜 데이터에 대해 포맷지정 후 Row 표시
 ***********************************************************************/
scwin.fn_setItem_Date = function(vIdx, strNm, strCd, dtsObj) {
    dts_List.setCellData(vIdx, 'ITEM', strNm);
    dts_List.setCellData(vIdx, 'NEWLIST_REQ', $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd)));
    dts_List.setCellData(vIdx, 'EXEM_REQ', $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd)));
    dts_List.setCellData(vIdx, 'CORRYN', scwin.fn_sameYn(dtsObj.getCellData(1, strCd), dtsObj.getCellData(2, strCd)));
};


/*********************************************************************** 
 * 함수명    : fn_setItem_Date2()
 * 파라메터 : vIdx(순서), strNm(항목명), strCd1(항목ID1), strCd2(항목ID2), dtsObj(데이터셋)
 * 설명       : 날짜 데이터에 대해 포맷지정 후 Row 표시
 ***********************************************************************/
scwin.fn_setItem_Date2 = function(vIdx, strNm, strCd1, strCd2, dtsObj) {
    var date1 = $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd1)) + " ~ " + $c.stf.FormatDateEx(dtsObj.getCellData(1, strCd2));
    var date2 = $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd1)) + " ~ " + $c.stf.FormatDateEx(dtsObj.getCellData(2, strCd2));
    dts_List.setCellData(vIdx, 'ITEM', strNm);
    dts_List.setCellData(vIdx, 'NEWLIST_REQ', date1);
    dts_List.setCellData(vIdx, 'EXEM_REQ', date2);
    dts_List.setCellData(vIdx, 'CORRYN', scwin.fn_sameYn(date1, date2));
};


/*********************************************************************** 
 * 함수명    : fn_setItem_Number()
 * 파라메터 : vIdx(순서), strNm(항목명), strCd(항목ID), dtsObj(데이터셋)
 * 설명       : 숫자 데이터에 대해 포맷지정 후 Row 표시
 ***********************************************************************/
scwin.fn_setItem_Number = function(vIdx, strNm, strCd, dtsObj) {
    dts_List.setCellData(vIdx, 'ITEM', strNm);
    var data1 = $c.stf.FormatNumberEx(dtsObj.getCellData(1, strCd));
    var data2 = $c.stf.FormatNumberEx(dtsObj.getCellData(2, strCd));
    if (strCd == 'ISU_LIMIT') {
        // % 관련 데이터는 여기 설정
        dts_List.setCellData(vIdx, 'NEWLIST_REQ', data1 + '%');
        dts_List.setCellData(vIdx, 'EXEM_REQ', data2 + '%');
    } else {
        dts_List.setCellData(vIdx, 'NEWLIST_REQ', data1);
        dts_List.setCellData(vIdx, 'EXEM_REQ', data2);
    }
    dts_List.setCellData(vIdx, 'CORRYN', scwin.fn_sameYn(dtsObj.getCellData(1, strCd), dtsObj.getCellData(2, strCd)));
};


/*********************************************************************** 
 * 함수명    : fn_setItem_yyyymm()
 * 파라메터 : vIdx(순서), strNm(항목명), strCd(항목ID), dtsObj(데이터셋)
 * 설명       : 일반 데이터에 대해 Row 표시
 ***********************************************************************/
scwin.fn_setItem_yyyymm = function(vIdx, strNm, strCd, dtsObj) {
    var ym1 = dtsObj.getCellData(1, strCd);
    var ym2 = dtsObj.getCellData(2, strCd);
    var data1 = "";
    var data2 = "";
    if (ym1.length == 6) {
        data1 = ym1.substring(0, 4) + "-" + ym1.substring(4, 6);
    } else {
        data1 = ym1;
    }
    if (ym2.length == 6) {
        data2 = ym2.substring(0, 4) + "-" + ym2.substring(4, 6);
    } else {
        data2 = ym2;
    }
    dts_List.setCellData(vIdx, 'ITEM', strNm);
    dts_List.setCellData(vIdx, 'NEWLIST_REQ', data1);
    dts_List.setCellData(vIdx, 'EXEM_REQ', data2);
    dts_List.setCellData(vIdx, 'CORRYN', scwin.fn_sameYn(ym1, ym2));
};


