/*********************************************************************** 
 * 함수명    : fn_sameYn()
 * 설명       : 일치여부 확인
 ***********************************************************************/
scwin.fn_sameYn = function(src1, src2) {
    if (src1 == src2) {
        return 'O';
    } else {
        return 'X';
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    var vHeadString = "ITEM:STRING(100),NEWLIST_REQ:STRING(300),EXEM_REQ:STRING(300),CORRYN:STRING(1)";
    //dts_List.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    var parentWin = $c.frame.path("../");
    var vViewCorrYnTyp = parentWin.vViewCorrYnTyp;
    var dtsObj = parentWin.dts_CorrYn;
    $c.stf.setObjectValue(txb_ISU_CD, dtsObj.getCellData(1, 'ISU_CD'));
    $c.stf.setObjectValue(txb_ISU_KOR_NM, dtsObj.getCellData(1, 'ISU_KOR_NM'));
    grd_List.Redraw = false;

    //일치항목 표시
    scwin.fn_setListingData(dtsObj);
    grd_List.redraw = true;
    dts_List.setRowPosition(1, 0);
};
